            -- inactive_border = colors.background,
        },

        layout = "dwindle",
    },

    decoration = {
        rounding = 10,

        active_opacity = 1.0,
        fullscreen_opacity = 1.0,

        -- shadow = {
        --     enabled = true,
        --     range = 6,
        --     render_power = 1,
        --     color = colors.color12,
        --     color_inactive = 0x50000000,
        -- },

        blur = {
            enabled = true,
